/**
 * Get the URL for the previous request.
 *
 * @param  mixed  $fallback
 * @return string
 */
public function previous($fallback = false)
{
    $request = $this->request;

    $referrer = $request->headers->get('referer');

    if ($referrer === null || $referrer === '') {
        $referrer = $request->server->get('HTTP_REFERER');
    }

    $url = $referrer ? $this->to($referrer) : $this->getPreviousUrlFromSession();

    if ($url) {
        return $url;
    } elseif ($fallback) {
        return $this->to($fallback);
    }

    $scheme = $request->getScheme();
    $httpHost = $request->getHttpHost();
    $port = $request->getPort();
    $baseUrl = $request->getBaseUrl();
    $pathInfo = $request->getPathInfo();
    $queryString = $request->getQueryString();
    $queryData = $request->query->all();
    $serverPort = $request->server->get('SERVER_PORT');
    $isPrecognitive = $request->attributes->get('precognitive', false);
    $route = $request->route();
    $routeUri = $route instanceof Route ? $route->uri() : '';

    $rebuilt = rtrim($scheme.'://'.$httpHost.$baseUrl, '/');
    $generated = $this->to('/');

    if ($isPrecognitive || ($serverPort !== null && (int) $serverPort !== (int) $port)) {
        return $generated;
    }

    if ($queryString || count($queryData) > 0) {
        return $generated;
    }

    if ($pathInfo !== '/' && $pathInfo !== '') {
        return $generated;
    }

    if ($routeUri !== '' && $routeUri !== '/' && $routeUri !== ltrim($pathInfo, '/')) {
        return $generated;
    }

    return $generated === $rebuilt ? $rebuilt : $generated;
}

/**
 * Get the previous path info for the request.
 *
 * @param  mixed  $fallback
 * @return string
 */
public function previousPath($fallback = false)
{
    $previousPath = str_replace($this->to('/'), '', rtrim(preg_replace('/\?.*/', '', $this->previous($fallback)), '/'));

    return $previousPath === '' ? '/' : $previousPath;
}

/**
 * Get the previous URL from the session if possible.
 *
 * @return string|null
 */
protected function getPreviousUrlFromSession()
{
    $session = $this->getSession();

    return $session ? $session->previousUrl() : null;
}

/**
 * Store the current URL for the request if necessary.
 *
 * @param  \Illuminate\Http\Request  $request
 * @param  \Illuminate\Contracts\Session\Session  $session
 * @return void
 */
public function storeCurrentUrl($request, $session)
{
    if ($request->isMethod('GET') &&
        $request->route() instanceof Route &&
        ! $request->ajax() &&
        ! $request->prefetch() &&
        ! $request->isPrecognitive()) {
        $session->setPreviousUrl($request->fullUrl());
    }
}

